    deepExplanation: "Step 1 — Directed graph with three states:\n0 = unvisited, 1 = visiting, 2 = fully processed.\n\nWITHOUT BUILT-IN / CORE:\n```ts\nfunction hasDirectedCycle(\n  graph: readonly (readonly number[])[],\n): boolean {\n  const state = new Array<0 | 1 | 2>(graph.length).fill(0);\n\n  function dfs(node: number): boolean {\n    if (state[node] === 1) return true;\n    if (state[node] === 2) return false;\n\n    state[node] = 1;\n\n    for (const next of graph[node] ?? []) {\n      if (dfs(next)) return true;\n    }\n\n    state[node] = 2;\n    return false;\n  }\n\n  for (let node = 0; node < graph.length; node++) {\n    if (state[node] === 0 && dfs(node)) return true;\n  }\n\n  return false;\n}\n```\n\nWITH BUILT-IN — Set recursion path:\n```ts\nfunction hasDirectedCycleUsingSets(\n  graph: readonly (readonly number[])[],\n): boolean {\n  const visiting = new Set<number>();\n  const visited = new Set<number>();\n\n  function dfs(node: number): boolean {\n    if (visiting.has(node)) return true;\n    if (visited.has(node)) return false;\n\n    visiting.add(node);\n\n    for (const next of graph[node] ?? []) {\n      if (dfs(next)) return true;\n    }\n\n    visiting.delete(node);\n    visited.add(node);\n\n    return false;\n  }\n\n  for (let node = 0; node < graph.length; node++) {\n    if (dfs(node)) return true;\n  }\n\n  return false;\n}\n```\n\nStep 2 — Example:\n0 → 1 → 2 → 0\nDFS reaches 0 while 0 is still \"visiting\" → cycle exists.\n\nStep 3 — Complexity:\nO(V + E) time and O(V) space.\n\nStep 4 — Important:\nFor an undirected graph, a visited neighbor is only a cycle if it is not the parent of the current node.",
