    deepExplanation: "Step 1 — Core structure.\n\nWITHOUT BUILT-IN / CORE:\n```ts\nclass UnionFind {\n  private readonly parent: number[];\n  private readonly size: number[];\n\n  constructor(count: number) {\n    this.parent = new Array<number>(count);\n    this.size = new Array<number>(count).fill(1);\n\n    for (let i = 0; i < count; i++) {\n      this.parent[i] = i;\n    }\n  }\n\n  find(value: number): number {\n    let root = value;\n\n    while (root !== this.parent[root]) {\n      root = this.parent[root]!;\n    }\n\n    while (value !== root) {\n      const next = this.parent[value]!;\n      this.parent[value] = root;\n      value = next;\n    }\n\n    return root;\n  }\n\n  union(a: number, b: number): boolean {\n    let rootA = this.find(a);\n    let rootB = this.find(b);\n\n    if (rootA === rootB) return false;\n\n    if (this.size[rootA]! < this.size[rootB]!) {\n      [rootA, rootB] = [rootB, rootA];\n    }\n\n    this.parent[rootB] = rootA;\n    this.size[rootA]! += this.size[rootB]!;\n\n    return true;\n  }\n\n  connected(a: number, b: number): boolean {\n    return this.find(a) === this.find(b);\n  }\n}\n```\n\nWITH BUILT-IN HELPERS — Map-backed DSU:\n```ts\nclass UnionFindUsingMap {\n  private readonly parent = new Map<number, number>();\n  private readonly size = new Map<number, number>();\n\n  constructor(count: number) {\n    for (let i = 0; i < count; i++) {\n      this.parent.set(i, i);\n      this.size.set(i, 1);\n    }\n  }\n\n  find(value: number): number {\n    let root = value;\n\n    while (this.parent.get(root) !== root) {\n      root = this.parent.get(root)!;\n    }\n\n    while (value !== root) {\n      const next = this.parent.get(value)!;\n      this.parent.set(value, root);\n      value = next;\n    }\n\n    return root;\n  }\n\n  union(a: number, b: number): boolean {\n    let rootA = this.find(a);\n    let rootB = this.find(b);\n\n    if (rootA === rootB) return false;\n\n    const sizeA = this.size.get(rootA)!;\n    const sizeB = this.size.get(rootB)!;\n\n    if (sizeA < sizeB) {\n      [rootA, rootB] = [rootB, rootA];\n    }\n\n    this.parent.set(rootB, rootA);\n    this.size.set(rootA, sizeA + sizeB);\n    return true;\n  }\n\n  connected(a: number, b: number): boolean {\n    return this.find(a) === this.find(b);\n  }\n}\n```\n\nStep 2 — Example:\nStart: {0},{1},{2},{3}\nunion(0,1) → {0,1},{2},{3}\nunion(2,3) → {0,1},{2,3}\nunion(1,2) → {0,1,2,3}\nconnected(0,3) → true.\n\nStep 3 — Complexity:\nWith path compression + union by size/rank:\nAmortized O(α(V)) per operation, effectively near O(1).\n\nStep 4 — Best use:\nDynamic connectivity where edges are added and you mainly ask whether two nodes belong to the same component.",
